SELECT b.*, u.name AS owner_name
FROM businesses b
LEFT JOIN users u ON b.owner_id = u.id


        AND b.name LIKE '%' || #{keyword} || '%'


        AND b.owner_id = #{ownerId}


        AND b.business_type = #{businessType}


        AND b.status = #{status}


ORDER BY b.created_at DESC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM businesses


        AND name LIKE '%' || #{keyword} || '%'


        AND owner_id = #{ownerId}


        AND business_type = #{businessType}


        AND status = #{status}

SELECT * FROM businesses
WHERE owner_id = #{ownerId}
ORDER BY created_at DESC

SELECT b.* FROM businesses b LEFT JOIN business_settings bs ON b.id = bs.business_id WHERE b.status = 'ACTIVE' AND COALESCE(bs.allow_online_booking, 'Y') = 'Y'
AND (b.name LIKE '%' || #{keyword} || '%' OR b.address LIKE '%' || #{keyword} || '%')
AND b.business_type = #{businessType}
ORDER BY b.average_rating DESC NULLS LAST ORDER BY b.name ASC ORDER BY b.created_at DESC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM businesses b LEFT JOIN business_settings bs ON b.id = bs.business_id WHERE b.status = 'ACTIVE' AND COALESCE(bs.allow_online_booking, 'Y') = 'Y'
AND (b.name LIKE '%' || #{keyword} || '%' OR b.address LIKE '%' || #{keyword} || '%')
AND b.business_type = #{businessType}
